-- Constant WHERE terms (sqlite3WhereBegin): a deterministic term with no
-- column reference is evaluated ONCE before the scan, in term order — an
-- error raises even over an empty table, a FALSE/NULL term stops before any
-- later term or row is evaluated; with GROUP BY, constant HAVING terms move
-- to WHERE (havingToWhere). LIMIT 0 precedes all of it (computeLimitRegisters).
CREATE TABLE t(x INTEGER PRIMARY KEY, y TEXT, z INTEGER);
CREATE TABLE e(x INTEGER, y TEXT);
CREATE INDEX t_y ON t(y);
INSERT INTO t VALUES (1,'a',10),(2,'b',-9223372036854775808),(3,'a',30);
SELECT 1 FROM t WHERE abs(-9223372036854775808) LIMIT 0;
SELECT 1 FROM e WHERE abs(-9223372036854775808);
SELECT 1 FROM t WHERE x > 5 AND abs(-9223372036854775808);
SELECT 1 FROM t WHERE x IN (1, abs(-9223372036854775808));
SELECT 1 FROM t WHERE NULL AND abs(-9223372036854775808);
SELECT 1 FROM t WHERE abs(-9223372036854775808) AND NULL;
SELECT 1 FROM t WHERE 0 AND abs(-9223372036854775808);
SELECT count(*) FROM t WHERE abs(-9223372036854775808);
SELECT count(*) FROM e WHERE abs(-9223372036854775808);
SELECT 1 FROM e GROUP BY x HAVING abs(-9223372036854775808);
SELECT count(*) FROM e HAVING abs(-9223372036854775808);
SELECT count(*), sum(z), max(y) FROM t WHERE 0;
SELECT count(*), sum(z), max(y) FROM t WHERE NULL;
SELECT y, count(*) FROM t WHERE 0 GROUP BY y;
SELECT count(*) FROM t WHERE 1=1 AND x > 1;
/*ordered*/ SELECT x, y FROM t WHERE 1 = 1 ORDER BY y DESC, x LIMIT 2;
/*ordered*/ SELECT x, y FROM t WHERE 2 > 1 AND y = 'a' ORDER BY x DESC LIMIT 5;
/*ordered*/ SELECT x FROM t WHERE 'a' < 'b' ORDER BY x DESC;
/*ordered*/ SELECT DISTINCT y FROM t WHERE 1 IN (1, 2) ORDER BY y;
SELECT x FROM t WHERE 1 IN (2, 3);
SELECT x FROM t WHERE coalesce(NULL, 0);
SELECT x FROM t WHERE length('abc') = 3 AND z > 0;
SELECT x FROM t WHERE lower('A') = 'a' COLLATE NOCASE;
SELECT x, sum(z) OVER () FROM t WHERE 0;
SELECT x, row_number() OVER (ORDER BY x) FROM t WHERE 1 + 1 = 2 AND x < 3;
SELECT * FROM (SELECT count(*) AS c FROM t) WHERE 0;
SELECT * FROM (SELECT count(*) AS c FROM t WHERE 0);
SELECT * FROM t AS a JOIN e ON a.x = e.x WHERE 0;
SELECT * FROM t AS a LEFT JOIN e ON a.x = e.x WHERE 'x' = 'x';
SELECT x FROM t WHERE 0 UNION SELECT x FROM e WHERE abs(-9223372036854775808);
SELECT x FROM t WHERE 1 UNION ALL SELECT x FROM t WHERE 0;
SELECT (SELECT count(*) FROM t WHERE 0), (SELECT max(x) FROM t WHERE 1 = 1);
SELECT x FROM t WHERE EXISTS (SELECT 1 FROM e WHERE abs(-9223372036854775808));
SELECT x FROM t WHERE (SELECT 1 FROM e WHERE abs(-9223372036854775808)) IS NULL;
SELECT x FROM t WHERE x = (SELECT max(x) FROM t WHERE 1) AND 'q' = 'q';
SELECT x FROM t WHERE random() > abs(-9223372036854775808);
SELECT x FROM e WHERE random() > abs(-9223372036854775808);
SELECT x FROM t WHERE date('now') IS NOT NULL AND x = 2;
SELECT x FROM t WHERE x > 1 AND 'abc' LIKE 'a%';
SELECT x FROM t WHERE CASE WHEN 1 THEN 1 END AND x < 3;
SELECT x FROM t WHERE CAST('1' AS INTEGER) AND z > 0;
SELECT x FROM t WHERE abs(z) > 0;
SELECT x FROM t WHERE 'a' GLOB 'b' OR x = 1;
INSERT INTO e SELECT x, y FROM t WHERE 0;
INSERT INTO e SELECT x, y FROM t WHERE 1 = 1 AND x < 3;
SELECT * FROM e ORDER BY x;
CREATE VIEW vv AS SELECT x, y FROM t WHERE 1 AND x > 1;
SELECT * FROM vv ORDER BY x;
WITH c AS (SELECT x FROM t WHERE 0) SELECT count(*) FROM c;
WITH c AS (SELECT x FROM t WHERE 1 = 1) SELECT count(*) FROM c WHERE 0;
